\begin{exercise}
\label{exer:trace-well-defined}
\dcref{chB:B.3}
Show that the trace on any pair of indices (one upper and one lower) is a well-defined linear map from $T^{(k+1,l+1)}(V)$ to $T^{(k,l)}(V)$.
\end{exercise}

